<template>
  <div class="min-w-0 space-y-4">
    <PageHeader :title="employeesOnly ? '员工信息管理' : '庆祝日历'" :description="employeesOnly ? '维护生日、入职日期与参与偏好，生日仅保存月日。' : '查看生日与入职周年，准备祝福贺卡和发送计划。'"><template #actions><Button variant="outline" size="sm" :disabled="busy" @click="refresh"><RefreshCw />刷新</Button><Button v-if="!employeesOnly" size="sm" :disabled="!sendableEmployees.length" @click="openSend()"><Send />发送祝福</Button></template></PageHeader>
    <SegmentedTabs v-if="!employeesOnly" v-model="tab" :items="[{ value: 'calendar', label: '庆祝日历' }, { value: 'employees', label: '员工与偏好' }, { value: 'cards', label: '祝福贺卡' }, { value: 'settings', label: '文案与计划' }, { value: 'logs', label: '发送记录' }]" />
    <template v-if="tab === 'calendar'">
      <section class="panel overflow-hidden">
        <div class="table-caption flex-wrap gap-3"><h2 class="panel-title">{{ month }} · {{ calendarError ? '–' : calendarLoading ? '正在加载…' : `${events.length} 项庆祝` }}</h2><div class="flex items-center gap-2"><Button variant="ghost" size="icon-sm" aria-label="上个月" @click="moveMonth(-1)"><ChevronLeft /></Button><Input id="celebration-month" v-model="month" type="month" class="h-8 w-36 text-xs" aria-label="查询月份" @change="loadCalendar" /><Button variant="ghost" size="icon-sm" aria-label="下个月" @click="moveMonth(1)"><ChevronRight /></Button><Button variant="outline" size="sm" @click="month = currentMonth; loadCalendar()">本月</Button></div></div>
        <Callout v-if="calendarError" tone="destructive" class="m-5" title="庆祝日历加载失败">{{ calendarError }}<template #action><Button variant="outline" size="sm" @click="loadCalendar">重试</Button></template></Callout>
        <p v-else-if="calendarLoading" class="py-10 text-center text-sm text-muted-foreground">正在加载日历…</p>
        <template v-else><div class="hidden grid-cols-7 border-t bg-muted/40 xl:grid"><span v-for="day in weekdays" :key="day" class="p-3 text-center text-xs font-medium text-muted-foreground">{{ day }}</span></div><div class="grid xl:grid-cols-7"><div v-for="(cell, i) in calendarCells" :key="i" class="border-t p-3 xl:min-h-28 xl:border-r" :class="[!cell.date || !cell.events.length ? 'hidden xl:block' : '', cell.date === today ? 'bg-primary/5' : '']"><p v-if="cell.date" class="mb-2 text-xs tabular-nums" :class="cell.date === today ? 'font-semibold text-primary' : 'text-muted-foreground'">{{ Number(cell.date.slice(-2)) }}<span class="ml-1 xl:hidden">日</span><span v-if="cell.date === today" class="ml-1">今天</span></p><button v-for="event in cell.events" :key="`${event.userId}-${event.kind}`" type="button" class="mb-1.5 block w-full rounded-lg border border-border bg-card px-2 py-1.5 text-left text-xs transition-colors hover:border-primary/40 disabled:cursor-default disabled:opacity-60" :disabled="event.optOut" :aria-label="`${event.name} · ${event.optOut ? '不参与祝福' : '发送祝福'}`" @click="openSend(event)"><span class="font-medium">{{ event.name }}</span><span class="ml-1 text-muted-foreground">{{ event.kind === 'birthday' ? '生日' : `${event.years} 周年` }}</span><span v-if="event.department" class="mt-1 block truncate text-[11px] text-muted-foreground">{{ event.department }}</span><span v-if="event.optOut" class="mt-1 block text-[11px] text-muted-foreground">不参与祝福</span></button></div></div><EmptyState v-if="!events.length" title="这个月没有庆祝安排" description="日历展示已录入日期的在职员工；不参与者仍在 HR 清单中展示。" /></template>
      </section>
    </template>
    <section v-else-if="tab === 'employees'" class="panel overflow-hidden">
      <form class="table-toolbar flex-wrap gap-2" @submit.prevent="loadEmployees"><Input v-model="employeeQuery" class="h-9 w-full text-[13px] sm:w-64" placeholder="搜索员工姓名或账号" aria-label="员工搜索" /><Button size="sm" type="submit" :disabled="employeesLoading"><Search />查询</Button><span class="ml-auto text-xs text-muted-foreground">生日仅显示月日</span></form>
      <Callout v-if="employeesError" class="m-5" tone="destructive" title="员工加载失败">{{ employeesError }}</Callout><p v-else-if="employeesLoading" class="py-10 text-center text-sm text-muted-foreground">正在加载员工…</p><EmptyState v-else-if="!employees.length" title="没有匹配的员工" />
      <div v-else class="max-h-[calc(100dvh-19rem)] overflow-auto border-t border-border/70"><table class="data-table min-w-[800px]"><thead><tr><th>员工</th><th>部门</th><th>生日（月日）</th><th>入职日期</th><th>状态</th><th>参与庆祝</th><th class="sticky-col text-right">操作</th></tr></thead><tbody><tr v-for="employee in employees" :key="employee.userId"><td><p class="font-medium">{{ employee.name }}</p><p class="mt-1 text-xs text-muted-foreground">{{ employee.username }}</p></td><td>{{ employee.department || '–' }}</td><td class="tabular-nums">{{ employee.birthday || '–' }}</td><td class="tabular-nums">{{ employee.hireDate?.slice(0, 10) || '–' }}</td><td><Badge :variant="flag(employee.enabled) ? 'success' : 'secondary'">{{ flag(employee.enabled) ? '在职' : '停用' }}</Badge></td><td><Switch :model-value="!employee.optOut" :disabled="busy" :aria-label="`${employee.name}参与庆祝`" @update:model-value="preference(employee, !$event)" /></td><td class="sticky-col"><div class="flex justify-end gap-1 whitespace-nowrap"><Button size="sm" variant="ghost" :disabled="busy" @click="openEmployee(employee)">编辑日期</Button><Button size="sm" variant="ghost" :disabled="busy || employee.optOut || !flag(employee.enabled)" @click="openSend(employee)">发送祝福</Button></div></td></tr></tbody></table></div>
    </section>
    <section v-else-if="tab === 'settings'" class="panel p-5">
      <h2 class="panel-title mb-4">庆祝文案与发送计划</h2><Callout v-if="settingsError" tone="destructive" title="配置加载失败">{{ settingsError }}<template #action><Button variant="outline" size="sm" @click="loadSettings">重试</Button></template></Callout>
      <form v-else-if="settings" class="space-y-5" @submit.prevent="saveSettings">
        <Callout v-if="settings.schedulerEnabled === false" tone="warning">当前自动发送已关闭，可通过「执行今日计划」手动发送。</Callout>
        <div class="flex items-center justify-between gap-4 rounded-lg border p-4"><div><label for="celebrations-enabled" class="text-sm font-medium">启用每日庆祝计划</label><p class="mt-1 text-xs text-muted-foreground">发送时间使用北京时间；发送结果可在记录中查询。</p></div><Switch id="celebrations-enabled" v-model="settings.enabled" /></div>
        <div class="grid gap-4 sm:grid-cols-2"><div><label for="celebration-time" class="field-label">计划发送时间</label><Input id="celebration-time" v-model="sendTime" type="time" required /></div><div class="flex items-center gap-3 pt-5"><Switch id="celebrations-birthday" v-model="settings.birthdayEnabled" /><label for="celebrations-birthday" class="text-sm">计划中发送生日祝福</label></div></div>
        <div class="flex items-center gap-3"><Switch id="celebrations-birthday-card" v-model="settings.birthdayCardEnabled" /><label for="celebrations-birthday-card" class="text-sm">额外发送生日图片贺卡链接</label></div>
        <p class="text-xs leading-6 text-muted-foreground">员工祝福支持 <code>{name}</code>（姓名）、<code>{years}</code>（入职周年数）；HR 汇总支持 <code>{year}</code>、<code>{month}</code>、<code>{date}</code>、<code>{count}</code>。每月 1 日发送本月预告，有庆祝安排的当天发送 HR 名单。</p>
        <div class="space-y-4 border-t pt-5"><div><h3 class="text-sm font-semibold">祝福与提醒文案</h3><p class="mt-1 text-xs text-muted-foreground">切换场景编辑文案，完成后统一保存。</p></div><SegmentedTabs v-model="templateGroup" :items="templateGroups" /><div v-for="template in visibleTemplateFields" :key="template.key"><label :for="`celebration-${template.key}`" class="field-label">{{ template.label }}</label><Input v-if="template.key.endsWith('_title')" :id="`celebration-${template.key}`" v-model="templateValues[template.key]" required maxlength="100" /><Textarea v-else :id="`celebration-${template.key}`" v-model="templateValues[template.key]" required maxlength="2000" :rows="4" /></div></div>
        <section class="rounded-lg border bg-muted/20 p-4" aria-label="当前祝贺文案预览"><h3 class="text-xs font-semibold text-muted-foreground">发送文案预览</h3><p class="mt-3 text-sm font-medium">{{ templatePreview.title }}</p><p class="mt-2 whitespace-pre-wrap break-words text-sm leading-7">{{ templatePreview.body }}</p><p class="mt-3 text-xs text-muted-foreground">变量在发送时按员工与日期替换；HR 汇总会追加实际人员名单。</p></section><Callout v-if="settingsSaveError" tone="destructive">{{ settingsSaveError }}</Callout>
        <div class="flex flex-wrap items-center gap-2 border-t pt-4"><Button type="submit" :loading="busy">保存文案与计划</Button><Button variant="ghost" :disabled="busy" @click="restoreDefaults">恢复当前场景默认文案</Button><Button variant="outline" class="sm:ml-auto" :disabled="busy" @click="runConfirm = true">执行今日计划</Button></div>
        <section v-if="settings.runs?.length" class="space-y-3 border-t pt-4"><h3 class="text-sm font-semibold">最近计划执行记录</h3><div class="overflow-x-auto rounded-lg border"><table class="data-table"><thead><tr><th>日期</th><th>计划</th><th>结果</th><th>发送统计</th></tr></thead><tbody><tr v-for="run in settings.runs" :key="run.id"><td>{{ run.runDate }}</td><td>{{ run.kind === 'monthly_digest' ? '本月 HR 预告' : run.kind === 'daily' ? '每日庆祝' : run.kind }}</td><td><Badge :variant="run.status === 'ok' ? 'success' : run.status === 'partial' ? 'warning' : 'destructive'">{{ run.status === 'ok' ? '已完成' : run.status === 'partial' ? '部分失败' : '失败' }}</Badge></td><td class="text-xs text-muted-foreground">{{ runSummary(run.detail) }}</td></tr></tbody></table></div></section>
      </form><p v-else class="text-sm text-muted-foreground">正在加载配置…</p>
    </section>
    <PortalCelebrationCards v-else-if="tab === 'cards'" :employees="sendableEmployees" @sent="loadLogs" />
    <section v-else class="panel overflow-hidden">
      <div class="table-caption"><h2 class="panel-title">发送记录</h2><Button variant="outline" size="sm" :disabled="logsLoading" @click="loadLogs">刷新</Button></div><Callout v-if="logsError" tone="destructive" class="m-5">{{ logsError }}</Callout><p v-else-if="logsLoading" class="py-10 text-center text-sm text-muted-foreground">正在加载记录…</p><EmptyState v-else-if="!logs.length" title="还没有发送记录" />
      <div v-else class="max-h-[calc(100dvh-19rem)] overflow-auto border-t border-border/70"><table class="data-table min-w-[800px]"><thead><tr><th>时间</th><th>收件人</th><th>类型 / 标题</th><th>结果</th><th>失败原因</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td class="whitespace-nowrap text-xs">{{ formatPortalDateTime(log.createdAt) }}</td><td>{{ employeeName(log.userId) }}</td><td><p>{{ log.title }}</p><p class="mt-1 text-xs text-muted-foreground">{{ kindName(log.kind) }}</p></td><td><Badge :variant="flag(log.sentOk) ? 'success' : 'destructive'">{{ flag(log.sentOk) ? '网关已接收' : '发送失败' }}</Badge></td><td class="max-w-72 text-xs text-muted-foreground">{{ log.errorMsg || '–' }}</td></tr></tbody></table></div><Pagination class="border-t px-5 py-3" :page="logPage" :page-size="20" :total="logTotal" @update:page="logPage = $event; loadLogs()" />
    </section>
    <Dialog :open="sendOpen" title="发送员工祝福" @update:open="!busy && (sendOpen = $event)">
      <form id="celebration-send-form" class="space-y-4" @submit.prevent="send"><Callout v-if="sendError" tone="destructive">{{ sendError }}</Callout><div><label for="celebration-recipient" class="field-label">收件人 *</label><Select id="celebration-recipient" v-model="sendForm.userId" :options="sendableEmployees.map(e => ({ value: e.userId, label: `${e.name} · ${e.department || e.username}` }))" /></div><div><label for="celebration-kind" class="field-label">祝福类型</label><Select id="celebration-kind" v-model="sendForm.kind" :options="[{ value: 'birthday', label: '生日祝福' }, { value: 'anniversary', label: '入职周年' }, { value: 'custom', label: '自定义祝福' }]" @update:model-value="fillMessage" /></div><div><label for="celebration-send-title" class="field-label">标题 *</label><Input id="celebration-send-title" v-model="sendForm.title" required maxlength="100" /></div><div><label for="celebration-send-message" class="field-label">祝福内容 *</label><Textarea id="celebration-send-message" v-model="sendForm.message" required maxlength="2000" :rows="6" /></div><p class="text-xs text-muted-foreground">确认内容后将通过企业微信发送给所选员工。</p></form>
      <template #footer><Button variant="outline" :disabled="busy" @click="sendOpen = false">取消</Button><Button type="submit" form="celebration-send-form" :loading="busy" :disabled="!sendForm.userId"><Send />发送祝福</Button></template>
    </Dialog>
    <Dialog :open="!!editingEmployee" :title="`员工日期 · ${editingEmployee?.name ?? ''}`" @update:open="!busy && !$event && (editingEmployee = null)">
      <form id="celebration-employee-form" class="space-y-4" @submit.prevent="saveEmployee"><Callout v-if="employeeSaveError" tone="destructive">{{ employeeSaveError }}</Callout><div><label for="celebration-employee-birthday" class="field-label">生日（月日）</label><Input id="celebration-employee-birthday" v-model="employeeForm.birthday" maxlength="5" pattern="[0-9]{2}-[0-9]{2}" placeholder="例如 06-18；留空清除" /><p class="mt-1 text-xs text-muted-foreground">生日仅维护月日，企微原始出生信息保留。</p></div><div><label for="celebration-employee-hire" class="field-label">入职日期</label><Input id="celebration-employee-hire" v-model="employeeForm.hireDate" type="date" :max="today" /></div><div class="flex items-center gap-3"><Switch id="celebration-employee-optout" v-model="employeeForm.optOut" /><label for="celebration-employee-optout" class="text-sm">不参与生日与入职周年庆祝</label></div></form><template #footer><Button variant="outline" :disabled="busy" @click="editingEmployee = null">取消</Button><Button type="submit" form="celebration-employee-form" :loading="busy">保存员工日期</Button></template>
    </Dialog>
    <ConfirmDialog :open="runConfirm" title="执行今日庆祝计划" description="按已保存的计划向今日过生日或入职周年的员工发送祝福，并发送 HR 名单；每月 1 日包含本月预告。系统会跳过已执行的计划。确认执行？" :busy="busy" @update:open="!busy && (runConfirm = $event)" @confirm="runToday" />
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChevronLeft, ChevronRight, RefreshCw, Search, Send } from '@lucide/vue'
import { api } from '../../lib/api'
import { errText, toast } from '../../lib/toast'
import PortalCelebrationCards from '../../components/portal/PortalCelebrationCards.vue'
import Badge from '../../ui/Badge.vue'
import Button from '../../ui/Button.vue'
import Callout from '../../ui/Callout.vue'
import ConfirmDialog from '../../ui/ConfirmDialog.vue'
import Dialog from '../../ui/Dialog.vue'
import EmptyState from '../../ui/EmptyState.vue'
import Input from '../../ui/Input.vue'
import PageHeader from '../../ui/PageHeader.vue'
import Pagination from '../../ui/Pagination.vue'
import SegmentedTabs from '../../ui/SegmentedTabs.vue'
import Select from '../../ui/Select.vue'
import Switch from '../../ui/Switch.vue'
import Textarea from '../../ui/Textarea.vue'
import { formatPortalDateTime } from '../../lib/portal-management-format'
interface Employee { userId: number; username: string; name: string; department?: string; birthday?: string; hireDate?: string; enabled: boolean | number; optOut?: boolean }
interface EventRow extends Employee { kind: string; date: string; years?: number }
interface Settings { enabled: boolean; sendHour: number; sendMinute: number; birthdayEnabled: boolean; birthdayCardEnabled: boolean; schedulerEnabled?: boolean; templates: Record<string, string>; templateDefaults: Record<string, string>; runs?: { id: number; runDate: string; kind: string; status: string; detail: unknown }[] }
interface PushLog { id: number; userId: number; kind: string; title: string; sentOk: boolean | number; errorMsg?: string; createdAt: string }
const base = '/admin-api/portal/celebrations'
const props = defineProps<{ employeesOnly?: boolean }>()
const route = useRoute(), router = useRouter()
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()), currentMonth = today.slice(0, 7)
const validMonth = (value: unknown) => typeof value === 'string' && /^\d{4}-(0[1-9]|1[0-2])$/.test(value) ? value : currentMonth
const tab = computed({
  get: () => props.employeesOnly ? 'employees' : ['calendar', 'employees', 'cards', 'settings', 'logs'].includes(String(route.query.tab)) ? String(route.query.tab) : 'calendar',
  set: (value: string) => { void router.push({ query: { ...route.query, tab: value } }) },
})
const month = ref(validMonth(route.query.month)), busy = ref(false), events = ref<EventRow[]>([]), calendarLoading = ref(false), calendarError = ref('')
const employees = ref<Employee[]>([]), employeeQuery = ref(''), employeesLoading = ref(false), employeesError = ref('')
const employeeDirectory = ref<Employee[]>([])
const settings = ref<Settings | null>(null), settingsError = ref(''), settingsSaveError = ref(''), sendTime = ref('09:00'), templateValues = reactive<Record<string, string>>({})
const templateFields = [{ key: 'birthday_title', label: '生日祝福标题' }, { key: 'birthday_body', label: '生日祝福正文' }, { key: 'anniversary_title', label: '入职周年标题' }, { key: 'anniversary_body', label: '入职周年正文' }, { key: 'monthly_title', label: 'HR 本月预告标题' }, { key: 'monthly_intro', label: 'HR 本月预告开场文案' }, { key: 'daily_title', label: 'HR 当日名单标题' }, { key: 'daily_intro', label: 'HR 当日名单开场文案' }]
const templateGroup = computed({
  get: () => ['birthday', 'anniversary', 'monthly', 'daily'].includes(String(route.query.template)) ? String(route.query.template) : 'birthday',
  set: (value: string) => { void router.push({ query: { ...route.query, tab: 'settings', template: value } }) },
})
const templateGroups = [{ value: 'birthday', label: '生日祝福' }, { value: 'anniversary', label: '入职周年' }, { value: 'monthly', label: 'HR 本月预告' }, { value: 'daily', label: 'HR 当日名单' }]
const visibleTemplateFields = computed(() => templateFields.filter(field => field.key.startsWith(templateGroup.value + '_')))
const templatePreview = computed(() => ({ title: templateValues[templateGroup.value + '_title'] || '填写标题后预览', body: templateValues[templateGroup.value + (['monthly', 'daily'].includes(templateGroup.value) ? '_intro' : '_body')] || '填写正文后预览' }))
const logs = ref<PushLog[]>([]), logPage = ref(1), logTotal = ref(0), logsLoading = ref(false), logsError = ref('')
const sendOpen = ref(false), sendError = ref(''), sendForm = reactive({ userId: null as number | null, kind: 'birthday', title: '', message: '', years: '' }), runConfirm = ref(false)
const editingEmployee = ref<Employee | null>(null), employeeSaveError = ref(''), employeeForm = reactive({ birthday: '', hireDate: '', optOut: false })
let calendarSeq = 0, employeeSeq = 0, logSeq = 0, settingsSeq = 0
const weekdays = ['一', '二', '三', '四', '五', '六', '日']
const flag = (value: boolean | number | undefined) => value === true || value === 1
const sendableEmployees = computed(() => employeeDirectory.value.filter(e => flag(e.enabled) && !e.optOut))
const calendarCells = computed(() => {
  const [year, m] = month.value.split('-').map(Number)
  if (!year || m < 1 || m > 12) return []
  const length = new Date(Date.UTC(year, m, 0)).getUTCDate(), offset = (new Date(Date.UTC(year, m - 1, 1)).getUTCDay() + 6) % 7
  const cells: { date: string; events: EventRow[] }[] = Array.from({ length: offset }, () => ({ date: '', events: [] }))
  for (let day = 1; day <= length; day++) { const date = `${month.value}-${String(day).padStart(2, '0')}`; cells.push({ date, events: events.value.filter(e => e.date === date) }) }
  return cells
})
const kindName = (kind: string) => ({ birthday: '生日', anniversary: '入职周年', custom: '自定义祝福', celebration_card: '贺卡链接', monthly_digest: 'HR 本月预告', daily_list: 'HR 当日名单' } as Record<string, string>)[kind] ?? kind
const employeeName = (id: number) => employeeDirectory.value.find(e => e.userId === id)?.name ?? `员工 #${id}`
async function loadCalendar() { const seq = ++calendarSeq; calendarLoading.value = true; calendarError.value = ''; try { if (validMonth(month.value) !== month.value) throw new Error('请选择有效月份'); const data = await api.get<EventRow[]>(`${base}/calendar`, { month: month.value }); if (seq === calendarSeq) events.value = data } catch (e) { if (seq === calendarSeq) { events.value = []; calendarError.value = errText(e) } } finally { if (seq === calendarSeq) calendarLoading.value = false } }
async function loadEmployees() { const seq = ++employeeSeq; employeesLoading.value = true; employeesError.value = ''; try { const data = await api.get<Employee[]>(`${base}/employees`, { q: employeeQuery.value }); if (seq === employeeSeq) { employees.value = data; if (!employeeQuery.value.trim()) employeeDirectory.value = data; else { const byId = new Map(employeeDirectory.value.map(e => [e.userId, e])); for (const employee of data) byId.set(employee.userId, employee); employeeDirectory.value = [...byId.values()] } } } catch (e) { if (seq === employeeSeq) employeesError.value = errText(e) } finally { if (seq === employeeSeq) employeesLoading.value = false } }
async function loadSettings() { const seq = ++settingsSeq; settingsError.value = ''; try { const data = await api.get<Settings>(`${base}/settings`); if (seq !== settingsSeq) return; settings.value = data; sendTime.value = `${String(data.sendHour).padStart(2, '0')}:${String(data.sendMinute).padStart(2, '0')}`; for (const field of templateFields) templateValues[field.key] = data.templates[field.key] ?? data.templateDefaults[field.key] ?? '' } catch (e) { if (seq === settingsSeq) settingsError.value = errText(e) } }
async function loadLogs() { const seq = ++logSeq; logsLoading.value = true; logsError.value = ''; try { const data = await api.get<{ list: PushLog[]; total: number }>(`${base}/push-logs`, { pageNo: logPage.value, pageSize: 20 }); if (seq === logSeq) { logs.value = data.list; logTotal.value = data.total } } catch (e) { if (seq === logSeq) logsError.value = errText(e) } finally { if (seq === logSeq) logsLoading.value = false } }
async function refresh() { await Promise.all([loadCalendar(), loadEmployees(), loadSettings(), loadLogs()]) }
function moveMonth(delta: number) { const validMonth = /^\d{4}-\d{2}$/.test(month.value) ? month.value : currentMonth; const [year, m] = validMonth.split('-').map(Number); const date = new Date(Date.UTC(year, m - 1 + delta, 1)); month.value = date.toISOString().slice(0, 7); void loadCalendar() }
async function preference(employee: Employee, optOut: boolean) { if (busy.value) return; busy.value = true; try { await api.put(`${base}/preference`, { userId: employee.userId, optOut }); employee.optOut = optOut; employeeDirectory.value = employeeDirectory.value.map(row => row.userId === employee.userId ? { ...row, optOut } : row); await loadCalendar(); toast('庆祝偏好已保存') } catch (e) { toast(errText(e), 'bad') } finally { busy.value = false } }
function openEmployee(employee: Employee) { editingEmployee.value = employee; Object.assign(employeeForm, { birthday: employee.birthday ?? '', hireDate: employee.hireDate?.slice(0, 10) ?? '', optOut: !!employee.optOut }); employeeSaveError.value = '' }
async function saveEmployee() {
  if (!editingEmployee.value || busy.value) return
  employeeSaveError.value = ''
  if (employeeForm.birthday) { const date = new Date(`2000-${employeeForm.birthday}T00:00:00Z`); if (Number.isNaN(date.getTime()) || date.toISOString().slice(5, 10) !== employeeForm.birthday) { employeeSaveError.value = '生日须为有效的 MM-DD 月日'; return } }
  busy.value = true
  try { const updated = await api.put<Employee>(`${base}/employee`, { userId: editingEmployee.value.userId, birthday: employeeForm.birthday || null, hireDate: employeeForm.hireDate || null, optOut: employeeForm.optOut }); employeeDirectory.value = employeeDirectory.value.map(row => row.userId === updated.userId ? updated : row); editingEmployee.value = null; await Promise.all([loadEmployees(), loadCalendar()]); toast('员工日期已保存') }
  catch (e) { employeeSaveError.value = errText(e) }
  finally { busy.value = false }
}
async function saveSettings() { if (!settings.value || busy.value) return; busy.value = true; settingsSaveError.value = ''; try { if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(sendTime.value)) throw new Error('请选择有效发送时间'); for (const field of templateFields) { const value = (templateValues[field.key] ?? '').trim(), limit = field.key.endsWith('_title') ? 100 : 2000; if (!value || value.length > limit) { templateGroup.value = field.key.split('_')[0]!; throw new Error(`${field.label}须为1至${limit}字`) } } const [sendHour, sendMinute] = sendTime.value.split(':').map(Number); settingsSeq++; settings.value = await api.put<Settings>(`${base}/settings`, { enabled: settings.value.enabled, birthdayEnabled: settings.value.birthdayEnabled, birthdayCardEnabled: settings.value.birthdayCardEnabled, sendHour, sendMinute, templates: { ...templateValues } }); toast('文案与计划已保存') } catch (e) { settingsSaveError.value = errText(e) } finally { busy.value = false } }
function restoreDefaults() { if (settings.value) for (const field of visibleTemplateFields.value) templateValues[field.key] = settings.value.templateDefaults[field.key] ?? '' }
function openSend(target?: Employee | EventRow) { if (target?.optOut) return; const id = target?.userId ?? sendableEmployees.value[0]?.userId ?? null; const kind = target && 'kind' in target ? target.kind : 'birthday'; Object.assign(sendForm, { userId: id, kind, title: '', message: '', years: target && 'years' in target ? String(target.years ?? '') : '' }); fillMessage(); sendError.value = ''; sendOpen.value = true }
function fillMessage() { const employee = employeeDirectory.value.find(e => e.userId === sendForm.userId), event = events.value.find(e => e.userId === sendForm.userId && e.kind === sendForm.kind); const years = event?.years ?? (employee?.hireDate ? Math.max(0, Number(month.value.slice(0, 4)) - Number(employee.hireDate.slice(0, 4))) : ''); const render = (value: string) => value.replaceAll('{name}', employee?.name ?? '').replaceAll('{years}', String(years)); if (sendForm.kind === 'custom') { sendForm.title = ''; sendForm.message = '' } else { const texts = { ...settings.value?.templateDefaults, ...settings.value?.templates }; sendForm.title = render(texts[`${sendForm.kind}_title`] ?? ''); sendForm.message = render(texts[`${sendForm.kind}_body`] ?? '') } }
async function send() { if (!sendForm.userId || busy.value) return; busy.value = true; sendError.value = ''; try { const result = await api.post<{ sentOk: boolean; errorMsg?: string }>(`${base}/send`, { userId: sendForm.userId, kind: sendForm.kind, title: sendForm.title.trim(), message: sendForm.message.trim() }, 60000); if (!result.sentOk) { sendError.value = result.errorMsg ?? '企微发送失败，请查看发送记录'; await loadLogs(); return } sendOpen.value = false; toast('祝福已提交到企业微信'); await loadLogs() } catch (e) { sendError.value = errText(e) } finally { busy.value = false } }
function runSummary(value: unknown) { try { const detail = typeof value === 'string' ? JSON.parse(value) : value; if (detail && typeof detail === 'object' && 'sent' in detail) return `成功 ${detail.sent ?? 0} 项，失败 ${detail.failed ?? 0} 项`; return '请查看发送记录' } catch { return '请查看发送记录' } }
async function runToday() { if (busy.value) return; busy.value = true; try { const result = await api.post<{ skipped?: boolean; daily?: { sent: number; failed: number }; monthlyDigest?: { sent: number; failed: number } }>(`${base}/run-now`, undefined, 180000); const results = [result.daily, result.monthlyDigest].filter((value): value is { sent: number; failed: number } => !!value); if (!results.length) toast('今日计划已执行或计划已关闭'); else { const sent = results.reduce((sum, r) => sum + Number(r.sent), 0), failed = results.reduce((sum, r) => sum + Number(r.failed), 0); toast(`成功发送 ${sent} 项，失败 ${failed} 项`, failed ? 'bad' : 'ok') } runConfirm.value = false; await Promise.all([loadLogs(), loadSettings()]) } catch (e) { toast(errText(e), 'bad') } finally { busy.value = false } }
watch(() => sendForm.userId, () => { if (sendOpen.value) fillMessage() })
watch(month, value => { if (validMonth(value) === value && value !== validMonth(route.query.month)) void router.replace({ query: { ...route.query, month: value } }) })
watch(() => route.query.month, value => { const next = validMonth(value); if (month.value !== next) { month.value = next; void loadCalendar() } })
onMounted(() => { void refresh() })
</script>
